{"path": "/harness-state/hermes/cache/scratch/mcp_call.py", "content": "import json, subprocess, sys, os
# usage: mcp_call.py <tool> '<json args>'   (or: mcp_call.py --schema <tool>)
env = dict(os.environ, GBRAIN_HOME="/harness-state",
           PATH="/harness-state/.bun/bin:" + os.environ.get("PATH", ""))
p = subprocess.Popen(["/harness-state/.bun/bin/gbrain", "serve", "--surface", "full"],
                     stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                     text=True, env=env)
def send(m): p.stdin.write(json.dumps(m) + "\n"); p.stdin.flush()
def recv(i):
    while True:
        line = p.stdout.readline()
        if not line: raise SystemExit("server closed")
        try: m = json.loads(line)
        except Exception: continue
        if m.get("id") == i: return m
send({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2025-06-18", "capabilities": {}, "clientInfo": {"name": "hermes-install-check", "version": "1"}}})
recv(1)
send({"jsonrpc": "2.0", "method": "notifications/initialized"})
if sys.argv[1] == "--schema":
    send({"jsonrpc": "2.0", "id": 2, "method": "tools/list"})
    for t in recv(2)["result"]["tools"]:
        if t["name"] in sys.argv[2:]: print(t["name"], json.dumps(t["inputSchema"])[:1500])
else:
    send({"jsonrpc": "2.0", "id": 2, "method": "tools/call", "params": {"name": sys.argv[1], "arguments": json.loads(sys.argv[2])}})
    r = recv(2)
    print(json.dumps(r.get("result", r), indent=1)[:3000])
p.stdin.close(); p.terminate(); p.wait(10)
"}

